<script lang="ts">
  import {onMount} from 'svelte';import {api} from '$lib/api';import {ArrowRight,Banknote,ClipboardList,FileCheck2,MessageSquare,TrendingDown,TrendingUp,Wallet} from 'lucide-svelte';
  let data:any={newEnquiries:0,activeApplications:0,todayIncome:0,todayExpense:0,todayProfit:0,totalDue:0,paymentsReceived:0},recent:any[]=[],loading=true,error='';
  const nf=new Intl.NumberFormat('en-BD',{maximumFractionDigits:2});const money=(v:number)=>`\u09F3${nf.format(Number(v)||0)}`;
  const metrics=[[MessageSquare,'New enquiries','newEnquiries',false],[ClipboardList,'Active applications','activeApplications',false],[TrendingUp,"Today's income",'todayIncome',true],[TrendingDown,"Today's expense",'todayExpense',true],[FileCheck2,"Today's profit",'todayProfit',true],[Wallet,'Outstanding due','totalDue',true],[Banknote,'Payments received','paymentsReceived',true]] as const;
  onMount(async()=>{try{const token=localStorage.getItem('bp_token');const headers={authorization:`Bearer ${token}`};const [dashboard,enquiries,applications]=await Promise.all([api<any>('/admin/dashboard',{headers}),api<any[]>('/admin/resources/enquiries',{headers}),api<any[]>('/admin/resources/applications',{headers})]);data=dashboard;recent=[...enquiries.slice(0,3).map(x=>({...x,kind:'Enquiry',title:x.name,meta:x.type})),...applications.slice(0,3).map(x=>({...x,kind:'Application',title:x.fullName,meta:x.reference}))].sort((a,b)=>+new Date(b.createdAt)-+new Date(a.createdAt)).slice(0,5)}catch(e){error=e instanceof Error?e.message:'Unable to load dashboard'}finally{loading=false}});
</script>
<svelte:head><title>Admin Dashboard — Bengal Port</title></svelte:head>
<div class="dashboard"><header><div><span>OVERVIEW</span><h1>Good day, Administrator.</h1><p>Here is what needs your attention across Bengal Port.</p></div><a class="primary" href="/admin/accounts">Open Hisab Kitab <ArrowRight size={17}/></a></header>{#if error}<div class="notice">{error}</div>{/if}<section class="metrics" aria-busy={loading}>{#each metrics as metric,i}<article style={`--delay:${i*35}ms`}><div class="metric-icon"><svelte:component this={metric[0]} size={20}/></div><span>{metric[1]}</span><b>{metric[3]?money(data[metric[2]]):nf.format(data[metric[2]]||0)}</b></article>{/each}</section><section class="lower"><div class="activity"><div class="section-title"><div><h2>Recent activity</h2><p>Newest enquiries and applications</p></div><a href="/admin/enquiries">View all</a></div>{#if loading}<div class="empty">Loading recent activity…</div>{:else if recent.length}{#each recent as item}<a class="activity-row" href={item.kind==='Enquiry'?'/admin/enquiries':'/admin/applications'}><i class:application={item.kind==='Application'}>{item.kind==='Enquiry'?'ENQ':'APP'}</i><div><b>{item.title}</b><span>{item.kind} · {item.meta}</span></div><time>{new Date(item.createdAt).toLocaleDateString('en-BD',{day:'numeric',month:'short'})}</time><ArrowRight size={16}/></a>{/each}{:else}<div class="empty">Nothing new yet.</div>{/if}</div><div class="quick"><div class="section-title"><div><h2>Quick actions</h2><p>Common administration tasks</p></div></div><a href="/admin/opportunities"><span>Manage opportunities</span><ArrowRight size={17}/></a><a href="/admin/content"><span>Edit website content</span><ArrowRight size={17}/></a><a href="/admin/payments"><span>Review payments and dues</span><ArrowRight size={17}/></a><a href="/admin/accounts"><span>Record income or expense</span><ArrowRight size={17}/></a></div></section></div>
<style>.dashboard{padding:clamp(1.25rem,3.5vw,3rem);max-width:100rem;margin:auto}.dashboard>header{display:flex;align-items:flex-end;justify-content:space-between;gap:2rem;margin-bottom:2rem}.dashboard header span{font-size:.72rem;letter-spacing:.14em;color:var(--gold-deep);font-weight:800}.dashboard h1{font-size:clamp(2rem,4vw,3rem);letter-spacing:-.04em;color:var(--heading);margin:.4rem 0}.dashboard header p,.section-title p{color:var(--muted);margin:0}.primary{display:inline-flex;align-items:center;gap:.6rem;background:var(--gold);color:var(--heading);text-decoration:none;padding:.8rem 1rem;border-radius:.75rem;font-weight:750;box-shadow:0 .45rem 1rem #a7751726;transition:transform 150ms var(--ease-out),box-shadow 180ms ease}.primary:active,.quick>a:active,.activity-row:active{transform:scale(.98)}.notice{background:#fff0f0;color:#8f2929;padding:.9rem 1rem;border-radius:.75rem;margin-bottom:1rem}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.8rem}.metrics article{background:#fff;border:1px solid #e1e6e9;border-radius:.9rem;padding:1.15rem;animation:metric-in 300ms var(--delay) var(--ease-out) both}.metric-icon{width:2.5rem;height:2.5rem;border-radius:.7rem;background:#f6f1e4;color:var(--gold-deep);display:grid;place-items:center}.metrics span{display:block;color:#6d7b89;font-size:.75rem;margin:1rem 0 .35rem}.metrics b{font-size:1.5rem;color:var(--heading);letter-spacing:-.03em}.lower{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(18rem,.7fr);gap:1rem;margin-top:1rem}.activity,.quick{background:#fff;border:1px solid #e1e6e9;border-radius:1rem;padding:1.2rem}.section-title{display:flex;justify-content:space-between;align-items:center;padding:.2rem .2rem 1rem}.section-title h2{font-size:1rem;color:var(--heading);margin:0 0 .25rem}.section-title p{font-size:.75rem}.section-title>a{font-size:.75rem;color:var(--gold-deep);font-weight:750}.activity-row{display:grid;grid-template-columns:2.7rem 1fr auto 1rem;align-items:center;gap:.8rem;padding:.8rem .35rem;border-top:1px solid #edf0f2;color:inherit;text-decoration:none;transition:background-color 160ms ease,transform 140ms var(--ease-out)}.activity-row>i{font-size:.58rem;font-style:normal;font-weight:850;color:#24705b;background:#e8f5ef;width:2.5rem;height:2.5rem;border-radius:.65rem;display:grid;place-items:center}.activity-row>i.application{color:#725b29;background:#faf1da}.activity-row b,.activity-row span{display:block}.activity-row b{font-size:.84rem;color:var(--heading)}.activity-row span,.activity-row time{font-size:.69rem;color:#7a8795;margin-top:.2rem}.quick>a{min-height:3.1rem;padding:.7rem .8rem;border-top:1px solid #edf0f2;color:#34495f;text-decoration:none;display:flex;align-items:center;justify-content:space-between;font-size:.8rem;font-weight:680;transition:background-color 160ms ease,transform 140ms var(--ease-out)}.empty{padding:2rem;text-align:center;color:var(--muted);font-size:.8rem}@media(hover:hover) and (pointer:fine){.primary:hover{transform:translateY(-.12rem);box-shadow:0 .75rem 1.4rem #a7751730}.activity-row:hover,.quick>a:hover{background:#faf8f1}}@keyframes metric-in{from{opacity:0;transform:translateY(.5rem)}to{opacity:1;transform:none}}@media(max-width:75rem){.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:48rem){.dashboard>header{align-items:flex-start;flex-direction:column}.lower{grid-template-columns:1fr}}@media(max-width:30rem){.metrics{grid-template-columns:1fr}.dashboard{padding:1rem}.activity-row{grid-template-columns:2.7rem 1fr 1rem}.activity-row time{display:none}}@media(prefers-reduced-motion:reduce){.metrics article{animation:none}.primary,.activity-row,.quick>a{transition:none}}</style>
